/* ============================ Peace In Pressure — site-wide brand layer ============================
   Tokens carry colour, type and radius (Design system). This file holds only what tokens cannot say. */

/* Accented capitals missing from Yacote fall back to Work Sans, wherever a name appears. */
@font-face { font-family: "Yacote"; src: url("/fonts/WorkSans.ttf") format("truetype"); font-weight: 100 900; font-display: swap; unicode-range: U+00C1, U+00C9, U+00D3, U+00D6, U+0150, U+00DA, U+00D1, U+010C, U+0106, U+0160, U+017D; }

html { scroll-behavior: smooth; background: #020617; overflow-x: clip; }
body { -webkit-font-smoothing: antialiased; overflow-x: clip;
  background: radial-gradient(120% 60% at 70% -10%, #0a2c46 0%, #041c30 40%, #020617 100%) no-repeat #020617; }
::selection { background: #d705dd; color: #fff; }

/* Spacing is set explicitly per band, so blocks carry no padding of their own. */
.bz-block { padding-block: 0; }
.bz-col > .bz-block + .bz-block, .bz-col > .bz-block + .bz-row, .bz-col > .bz-row + .bz-block { margin-top: var(--space-4); }

/* On this dark site the ink token is the text colour, so the prebuilt dark bands take the card surface instead. */
.bz-block--hero, .bz-block--statBand, .bz-block--serviceGrid, .bz-block--footer, .bz-section--bg-ink, .bz-col--bg-ink { background: var(--card); color: var(--ink); }

/* Display type is always Yacote, uppercase. */
.bz-block :is(h1, h2, h3) { text-transform: uppercase; color: #f4fbff; }
.bz-block h1 { font-weight: 700; font-size: clamp(44px, 7vw, var(--text-h1)); line-height: .92; letter-spacing: 0; white-space: pre-line; }
.bz-block h2 { font-weight: 600; font-size: clamp(36px, 5vw, var(--text-h2)); line-height: .95; letter-spacing: 0; white-space: pre-line; }
.bz-block h3 { font-weight: 600; }
.bz-block p { font-size: var(--text-body); }
.bz-eyebrow { font-family: var(--font-heading); font-weight: 400; letter-spacing: .3em; }
.bz-text a, .bz-lede a { color: var(--accent); text-decoration: underline; text-underline-offset: 3px; }
.bz-text a:hover { color: var(--accent-dark); }
.bz-text strong { color: #f4fbff; font-weight: 600; }

/* Logos keep their set height (the block default is overridden by .bz-block img) */
.bz-block--logo .bz-logo__img { height: var(--bz-logo-h, 34px); width: auto; max-width: none; }

/* Buttons */
.bz-btn { font-family: var(--font-heading); font-weight: 600; font-size: 13px; letter-spacing: .12em; text-transform: uppercase; border-radius: 4px; padding: 14px 26px; line-height: 1; transition: transform .25s ease, border-color .25s ease, color .25s ease, filter .25s ease; }
.bz-btn--primary { background: linear-gradient(135deg, #00fbff, #00cdfd); color: #020617; border-color: transparent; padding: 10px 22px; }
.bz-btn--primary:hover { background: linear-gradient(135deg, #00fbff, #00cdfd); filter: brightness(1.08); transform: translateY(-1px); }
.bz-btn--secondary { background: transparent; color: #f4fbff; border-color: rgba(255,255,255,.25); }
.bz-btn--secondary:hover { border-color: #00cdfd; color: #00fbff; }
.bz-btn--link { color: #00cdfd; text-decoration: none; letter-spacing: .1em; }
.bz-btn--link:hover { color: #00fbff; }
[data-bz-node="fa-cta"] .bz-btn--primary, [data-bz-node="fa-close-cta"] .bz-btn--primary { padding: 16px 32px; font-size: 14px; }

/* Forms */
.bz-form { background: transparent; border: 0; padding: 0; max-width: none; gap: var(--space-4); }
.bz-form__t { display: none; }
.bz-form h2, .bz-form .bz-headingblock h2 { font-size: 28px; }
.bz-input, .bz-form input:not([type="checkbox"]):not([type="radio"]), .bz-form select, .bz-form textarea { background: rgba(4,28,48,.7); border: 1px solid rgba(255,255,255,.14); border-radius: 6px; color: #eaf2f8; font-family: var(--font-body); font-size: 15px; font-weight: 400; padding: 14px 16px; min-height: 48px; outline: none; }
.bz-input:focus, .bz-form select:focus, .bz-form textarea:focus, .bz-form input:focus { border-color: #00cdfd; outline: none; }
.bz-input::placeholder { color: #6f8598; }
.bz-form select option { background: #041c30; color: #eaf2f8; }
.bz-label { font-family: var(--font-body); font-weight: 500; font-size: 13px; letter-spacing: .06em; color: #c4d4e2; }
.bz-form button[type="submit"] { font-family: var(--font-heading); font-weight: 600; letter-spacing: .12em; text-transform: uppercase; font-size: 14px; color: #020617; background: linear-gradient(135deg, #00fbff, #00cdfd); border: 0; border-radius: 6px; padding: 15px 34px; cursor: pointer; }
.bz-form a { color: var(--accent); }

/* Rise-in on first view. Only armed once the script has run, so the editing canvas and no-JS visitors see everything. */
.pip-reveal-ready [data-bz-reveal] { opacity: 0; transform: translateY(30px); transition: opacity .8s ease, transform .8s ease; }
.pip-reveal-ready [data-bz-reveal].is-in { opacity: 1; transform: none; }

/* Inner pages — header copy */
[data-bz-node="fa-lede"] p, [data-bz-node="ap-lede"] p, [data-bz-node="pt-lede"] p, [data-bz-node="ct-lede"] p { font-size: 19px; font-weight: 300; line-height: 1.55; color: #9fb4c6; max-width: 560px; margin: 22px 0 0; }
[data-bz-node="fa-title"] h1, [data-bz-node="ap-title"] h1, [data-bz-node="pt-title"] h1, [data-bz-node="ct-title"] h1 { margin: 0; }
[data-bz-node="ap-points"] p { margin: 0 0 8px; font-size: 15px; color: #c4d4e2; }
[data-bz-node="ap-points"] { margin-top: 24px; }
[data-bz-node="ct-email"] p { margin: 28px 0 6px; }
[data-bz-node="ct-address"] p { margin: 0; font-size: 15px; color: #9fb4c6; }
[data-bz-node="pt-form-block"] h2 { font-size: 30px; }
[data-bz-node="pt-more"] p { margin-top: 24px; color: #9fb4c6; }

/* For Athletes */
[data-bz-node="fa-quote"] .bz-quote { background: rgba(4,28,48,.6); border: 1px solid rgba(255,255,255,.1); border-radius: 16px; padding: 32px; }
[data-bz-node="fa-quote"] .bz-quote blockquote { font-size: 17px; font-weight: 300; line-height: 1.6; color: #eaf2f8; }
[data-bz-node="fa-quote"] .bz-quote__n { font-family: var(--font-heading); letter-spacing: .1em; text-transform: uppercase; color: #00cdfd; font-size: 13px; }
[data-bz-node="fa-quote"] .bz-quote__r { color: #9fb4c6; }
[data-bz-node="fa-stats"] { background: transparent; padding-block: 0; }
[data-bz-node="fa-stats"] .bz-band { display: block; }
[data-bz-node="fa-stats"] .bz-stats { grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 24px; }
[data-bz-node="fa-stats"] .bz-stat { border-left: 1px solid rgba(255,255,255,.14); padding-left: 20px; }
[data-bz-node="fa-stats"] .bz-stat__v { font-family: var(--font-heading); font-weight: 700; font-size: clamp(30px, 3.4vw, 44px); color: #00fbff; }
[data-bz-node="fa-stats"] .bz-stat__l { color: #9fb4c6; font-size: 15px; line-height: 1.5; }
[data-bz-node="fa-terms-note"] p { margin-top: 28px; color: #9fb4c6; }
[data-bz-node="fa-steps"] { counter-reset: step; }
[data-bz-node="fa-steps"] .bz-quick { counter-increment: step; border-top: 1px solid rgba(255,255,255,.14); }
[data-bz-node="fa-steps"] .bz-quick::before { content: "0" counter(step); display: block; font-family: var(--font-heading); font-size: 13px; letter-spacing: .3em; color: #00cdfd; margin-bottom: 10px; }
[data-bz-node="fa-steps"] .bz-quick__t { font-family: var(--font-heading); text-transform: uppercase; letter-spacing: .04em; color: #f4fbff; }
[data-bz-node="fa-steps"] .bz-quick__d { color: #9fb4c6; }
[data-bz-node="fa-faq-items"] .bz-faq { background: transparent; border: 0; border-bottom: 1px solid rgba(255,255,255,.12); border-radius: 0; padding: 18px 0; }
[data-bz-node="fa-faq-items"] summary { cursor: pointer; font-family: var(--font-heading); font-weight: 600; letter-spacing: .04em; text-transform: uppercase; color: #f4fbff; list-style: none; }
[data-bz-node="fa-faq-items"] summary::-webkit-details-marker { display: none; }
[data-bz-node="fa-faq-items"] summary::after { content: "+"; float: right; color: #00cdfd; }
[data-bz-node="fa-faq-items"] details[open] summary::after { content: "–"; }
[data-bz-node="fa-faq-items"] .bz-faq__a { color: #9fb4c6; font-size: 16px; }
[data-bz-node="pt-list"] .bz-feature { background: transparent; border: 0; border-bottom: 1px solid rgba(255,255,255,.12); border-radius: 0; padding: 18px 0; }
[data-bz-node="pt-list"] .bz-feature__t { font-family: var(--font-heading); text-transform: uppercase; letter-spacing: .04em; color: #f4fbff; }
[data-bz-node="pt-list"] .bz-feature__d { color: #9fb4c6; font-size: 15px; }

/* Long-form legal text */
[data-bz-node="legal"] > .bz-container { max-width: 820px; }
[data-bz-node="legal-title"] h1 { font-size: clamp(40px, 6vw, 72px); margin: 0 0 18px; }
[data-bz-node="legal"] .bz-text p { font-size: 16px; line-height: 1.7; color: #c4d4e2; margin: 0 0 14px; max-width: none; text-wrap: pretty; }
[data-bz-node="legal"] .bz-headingblock h2 { font-size: 26px; line-height: 1.1; margin: 52px 0 16px; scroll-margin-top: 110px; }
[data-bz-node="legal"] .bz-headingblock h3 { font-family: var(--font-body); text-transform: none; font-weight: 600; font-size: 18px; line-height: 1.35; color: #00cdfd; margin: 30px 0 10px; scroll-margin-top: 110px; }
[data-bz-node="legal"] :is(h2, h3)[id] { scroll-margin-top: 110px; }

js:
// Rise-in on first view for the home page bands. Armed only once this script has run.
(function () {
  var names = ['news-stories', 'join-cta', 'partner-strip'];
  var hosts = names.map(function (n) { return document.querySelector('[data-bz-section="' + n + '"]'); }).filter(Boolean);
  if (!hosts.length || !('IntersectionObserver' in window)) return;
  if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  hosts.forEach(function (h) { h.setAttribute('data-bz-reveal', ''); });
  document.documentElement.classList.add('pip-reveal-ready');
  var io = new IntersectionObserver(function (entries) {
    entries.forEach(function (e) { if (e.isIntersecting) { e.target.classList.add('is-in'); io.unobserve(e.target); } });
  }, { threshold: 0.1 });
  hosts.forEach(function (h) { io.observe(h); });
})();
